//! Cross-checks against the ground-truth fixtures (tests/fixtures.json),
//! generated by tools/gen-fixtures.mjs:
//!
//!   * PDA vectors  — derived with the official SDK's findProgramAddressSync
//!   * tx_claim_b58 — serialized with web3.js Transaction.serialize (official
//!     legacy wire format), unsigned, durable-nonce
//!   * account bytes — PositionV2 / LbPair / BinArray laid out from the
//!     program IDL (bytemuck C-repr), sized 8120 / 888 / 10136
//!   * nonce_account — System-Program nonce layout (hash at offset 40)
//!
//! The instruction fixtures in the same JSON (claim_ix / remove_ix / add_ix)
//! are hand-encoded from the same IDL spec this crate implements — they pin
//! the Rust encoder against the spec, not against an independent source.

use base64::Engine;
use dlmm_core::decoder::{
    claimable_fees, claimable_fees_with_bins, decode_bin_array, decode_lb_pair, decode_position,
    fee_recipient, position_amounts, total_liquidity_shares, BIN_ARRAY_LEN, LB_PAIR_LEN,
    POSITION_V2_LEN,
};
use dlmm_core::nonce::{decode_nonce_hash, is_settled, nonce_hash_base58};
use dlmm_core::pda;
use dlmm_core::tx::{
    associated_token_address, bin_array_metas, bin_id_to_bin_array_index, build_claim_instructions,
    encode_unsigned_tx, PoolCtx, TOKEN_PROGRAM_ID,
};
use dlmm_core::validate::{
    validate_active_bin_slippage, validate_bin_array_range, validate_claimable, validate_owned,
    validate_range, ValidationError, MAX_ACTIVE_BIN_SLIPPAGE,
};
use serde_json::Value;
use solana_pubkey::Pubkey;

fn fixtures() -> Value {
    serde_json::from_str(include_str!("fixtures.json")).expect("fixtures.json parses")
}

fn pk(v: &Value) -> Pubkey {
    v.as_str().unwrap().parse().unwrap()
}

fn b64(v: &Value) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD
        .decode(v.as_str().unwrap())
        .unwrap()
}

fn b58(s: &str) -> Vec<u8> {
    bs58::decode(s).into_vec().unwrap()
}

// ---------------------------------------------------------------------------
// PDA cross-check (SDK findProgramAddressSync ground truth)
// ---------------------------------------------------------------------------

#[test]
fn pdas_match_sdk_derivation() {
    let f = fixtures();
    let pool = pk(&f["keys"]["pool"]);
    let program = pk(&f["keys"]["program"]);

    assert_eq!(
        pda::bin_array(&pool, 120, &program).0.to_string(),
        f["pdas"]["bin_array_120"]
    );
    assert_eq!(
        pda::bin_array(&pool, 121, &program).0.to_string(),
        f["pdas"]["bin_array_121"]
    );
    assert_eq!(
        pda::bin_array(&pool, -1, &program).0.to_string(),
        f["pdas"]["bin_array_neg1"]
    );
    assert_eq!(
        pda::event_authority(&program).0.to_string(),
        f["pdas"]["event_authority"]
    );
    assert_eq!(
        pda::bin_array_bitmap_extension(&pool, &program)
            .0
            .to_string(),
        f["pdas"]["bitmap_extension"]
    );
}

