#[test]
fn decodes_position_v2_from_fixture() {
    let f = fixtures();
    let pos = decode_position(&b64(&f["position_v2"])).expect("decode");

    assert_eq!(pos.lb_pair.to_string(), f["keys"]["pool"]);
    assert_eq!(pos.owner.to_string(), f["keys"]["owner"]);
    assert_eq!(pos.lower_bin_id, 8450);
    assert_eq!(pos.upper_bin_id, 8520);
    assert_eq!(pos.version, 2);

    // non-empty bins at index 0 and 5
    assert_eq!(pos.liquidity_shares[0], 1_000_000_000);
    assert_eq!(pos.liquidity_shares[5], 500_000_000);
    assert_eq!(pos.liquidity_shares[1], 0);
    assert_eq!(pos.fee_infos[0].fee_x_pending, 1_000_000);
    assert_eq!(pos.fee_infos[5].fee_y_pending, 2_000_000);

    let (fx, fy) = claimable_fees(&pos);
    assert_eq!((fx, fy), (1_000_000, 2_000_000));
    assert_eq!(total_liquidity_shares(&pos), 1_500_000_000);
    // fee_owner == owner in the fixture → recipient is owner
    assert_eq!(fee_recipient(&pos), pos.owner);
}

#[test]
fn decodes_lb_pair_from_fixture() {
    let f = fixtures();
    let lb = decode_lb_pair(&b64(&f["lb_pair"])).expect("decode");

    assert_eq!(lb.active_id, 8500);
    assert_eq!(lb.bin_step, 10);
    assert_eq!(lb.token_x_mint.to_string(), f["keys"]["token_x_mint"]);
    assert_eq!(lb.token_y_mint.to_string(), f["keys"]["token_y_mint"]);
    assert_eq!(lb.reserve_x.to_string(), f["keys"]["reserve_x"]);
    assert_eq!(lb.reserve_y.to_string(), f["keys"]["reserve_y"]);
}

#[test]
fn decodes_bin_array_from_fixture() {
    let f = fixtures();
    let ba = decode_bin_array(&b64(&f["bin_array"])).expect("decode");

    assert_eq!(ba.index, 120);
    assert_eq!(ba.lb_pair.to_string(), f["keys"]["pool"]);
    assert_eq!(ba.bins[0].amount_x, 2_000_000_000);
    assert_eq!(ba.bins[0].amount_y, 300_000_000);
    assert_eq!(ba.bins[0].liquidity_supply, 2_000_000_000);
    assert_eq!(ba.bins[1].liquidity_supply, 0);
    assert_eq!(ba.bins[69].amount_x, 0);
}

#[test]
fn position_amounts_matches_share_times_reserve_ratio() {
    let f = fixtures();
    let pos = decode_position(&b64(&f["position_v2"])).expect("decode position");
    // Aligned fixture: array 120 covers bins 8400..8469, so position bins
    // 8450 (share idx 0) and 8455 (share idx 5) live at inner offsets 50/55.
    let ba = decode_bin_array(&b64(&f["bin_array_aligned"])).expect("decode aligned bin array");

    let (x, y) = position_amounts(&pos, &[ba]);

    // share 1e9 in bin 8450: liquidity 2e9, amounts 2e9/3e8
    //   → x = 1e9 * 2e9 / 2e9 = 1_000_000_000, y = 1e9 * 3e8 / 2e9 = 150_000_000
    // share 5e8 in bin 8455: liquidity 1e9, amounts 1e9/1e8
    //   → x = 5e8 * 1e9 / 1e9 = 500_000_000,  y = 5e8 * 1e8 / 1e9 = 50_000_000
    assert_eq!((x, y), (1_500_000_000, 200_000_000));
}

#[test]
fn position_amounts_is_zero_without_bin_arrays() {
    let f = fixtures();
    let pos = decode_position(&b64(&f["position_v2"])).expect("decode position");
    assert_eq!(position_amounts(&pos, &[]), (0, 0));
}

// The per-bin per-token claimable math: the position's raw `fee_x_pending`
// undercounts fees accrued since the last claim. This pins the correct
// formula:
//   new_fee = (share >> SCALE_OFFSET) * (bin_fee_stored - fee_complete)
//            >> SCALE_OFFSET
//   claimable = new_fee + fee_pending
#[test]
fn claimable_fees_uses_per_bin_per_token_math() {
    let f = fixtures();
    let pos = decode_position(&b64(&f["position_v2"])).expect("decode position");
    let mut ba = decode_bin_array(&b64(&f["bin_array_aligned"])).expect("decode aligned bin array");

    // Position bin 8450 = inner offset 50 in array 120 (covers 8400..8469).
    // Position liquidity_shares[0] → that bin; the position's fee_infos[0].
    let bin_idx = 50usize;
    let share = pos.liquidity_shares[0];
    let fee_pending_x = pos.fee_infos[0].fee_x_pending;
    assert!(share > 0, "fixture position must hold liquidity at bin 8450");
    assert!(fee_pending_x > 0, "fixture position must have pending fees");

    // Give the bin a per-token stored fee above the position's last-claimed
    // value, so the per-token delta term is non-zero.
    let delta_per_token: u128 = 1 << 10; // in Q64.64 units
    ba.bins[bin_idx].fee_amount_x_per_token_stored =
        pos.fee_infos[0].fee_x_per_token_complete + delta_per_token;

    let (x, _y) = claimable_fees_with_bins(&pos, &[ba]);
    // expected = ((share >> 64) * delta_per_token) >> 64 + fee_pending_x
    let expected = (((share >> 64) as u128 * delta_per_token) >> 64) as u64 + fee_pending_x;
    assert_eq!(x, expected, "per-token delta term must be added to pending");
}

#[test]
fn rejects_wrong_discriminator_and_short_data() {
    let mut data = vec![0u8; POSITION_V2_LEN];
    data[..8].copy_from_slice(&[1, 2, 3, 4, 5, 6, 7, 8]);
    assert!(decode_position(&data).is_err());

    let mut ok = vec![0u8; POSITION_V2_LEN];
    ok[..8].copy_from_slice(&dlmm_core::decoder::POSITION_V2_DISCRIMINATOR);
    assert!(decode_position(&ok[..ok.len() - 1]).is_err());
    assert!(decode_position(&ok).is_ok());

    assert_eq!(LB_PAIR_LEN, 888);
    assert_eq!(BIN_ARRAY_LEN, 10136);
}

