#[test]
fn nonce_hash_extraction_matches_fixture() {
    let f = fixtures();
    let data = b64(&f["nonce_account"]);
    assert_eq!(data.len(), 80); // 4 + 4 + 32 + 32 + 8

    let hash = decode_nonce_hash(&data).expect("decode");
    assert_eq!(bs58::encode(hash).into_string(), f["keys"]["nonce_hash"]);
    assert_eq!(nonce_hash_base58(&data).unwrap(), f["keys"]["nonce_hash"]);

    // settlement evidence
    let mut changed = hash;
    changed[0] ^= 0x01;
    assert!(is_settled(&hash, &changed));
    assert!(!is_settled(&hash, &hash));
    assert!(decode_nonce_hash(&data[..39]).is_err());
}

