#[test]
fn ata_derivation_matches_web3js_ground_truth() {
    let f = fixtures();
    let owner = pk(&f["keys"]["owner"]);
    let token_program = TOKEN_PROGRAM_ID.parse().unwrap();
    let x = associated_token_address(&owner, &pk(&f["keys"]["token_x_mint"]), &token_program);
    let y = associated_token_address(&owner, &pk(&f["keys"]["token_y_mint"]), &token_program);
    assert_eq!(x.to_string(), f["keys"]["user_token_x"]);
    assert_eq!(y.to_string(), f["keys"]["user_token_y"]);
}

fn fixture_pool_ctx(f: &Value) -> PoolCtx {
    PoolCtx {
        lb_pair: pk(&f["keys"]["pool"]),
        reserve_x: pk(&f["keys"]["reserve_x"]),
        reserve_y: pk(&f["keys"]["reserve_y"]),
        token_x_mint: pk(&f["keys"]["token_x_mint"]),
        token_y_mint: pk(&f["keys"]["token_y_mint"]),
        token_program: TOKEN_PROGRAM_ID.parse().unwrap(),
    }
}

#[test]
fn claim_ix_matches_idl_layout() {
    let f = fixtures();
    let pool = fixture_pool_ctx(&f);
    let program = pk(&f["keys"]["program"]);
    let event_authority = pda::event_authority(&program).0;
    let bin_arrays: Vec<solana_pubkey::Pubkey> =
        bin_array_metas(&pool.lb_pair, 8450, 8520, &program)
            .into_iter()
            .map(|m| m.pubkey)
            .collect();

    let ix = dlmm_core::tx::claim_fee2_ix(
        &pool,
        pk(&f["keys"]["position"]),
        pk(&f["keys"]["owner"]),
        pk(&f["keys"]["user_token_x"]),
        pk(&f["keys"]["user_token_y"]),
        8450,
        8520,
        bin_arrays.clone(),
        dlmm_core::tx::MEMO_PROGRAM_ID.parse().unwrap(),
        event_authority,
        program,
    );

    let expected: Value = f["claim_ix"].clone();
    assert_eq!(ix.program_id.to_string(), expected["program_id"]);
    assert_eq!(ix.data, b64(&expected["data"]));
    let keys: Vec<(String, bool, bool)> = ix
        .accounts
        .iter()
        .map(|m| (m.pubkey.to_string(), m.is_signer, m.is_writable))
        .collect();
    let exp_keys: Vec<(String, bool, bool)> = expected["keys"]
        .as_array()
        .unwrap()
        .iter()
        .map(|k| {
            (
                k["pubkey"].as_str().unwrap().to_string(),
                k["isSigner"].as_bool().unwrap(),
                k["isWritable"].as_bool().unwrap(),
            )
        })
        .collect();
    assert_eq!(keys, exp_keys);
    assert_eq!(bin_arrays.len(), 2);
}

#[test]
fn bin_array_index_math_is_floor_div() {
    assert_eq!(bin_id_to_bin_array_index(8450), 120);
    assert_eq!(bin_id_to_bin_array_index(8520), 121);
    assert_eq!(bin_id_to_bin_array_index(0), 0);
    assert_eq!(bin_id_to_bin_array_index(69), 0);
    assert_eq!(bin_id_to_bin_array_index(70), 1);
    assert_eq!(bin_id_to_bin_array_index(-1), -1);
    assert_eq!(bin_id_to_bin_array_index(-70), -1);
    assert_eq!(bin_id_to_bin_array_index(-71), -2);
}

// ---------------------------------------------------------------------------
// Full transaction wire format (web3.js serialize ground truth)
// ---------------------------------------------------------------------------

#[test]
fn unsigned_claim_tx_matches_web3js_wire_format() {
    let f = fixtures();
    let pool = fixture_pool_ctx(&f);
    let program = pk(&f["keys"]["program"]);
    let nonce = pk(&f["keys"]["nonce"]);
    let owner = pk(&f["keys"]["owner"]);
    let position = pk(&f["keys"]["position"]);

    let blockhash: [u8; 32] = b58(f["keys"]["nonce_hash"].as_str().unwrap())
        .try_into()
        .unwrap();

    let ixs = build_claim_instructions(
        nonce,
        owner,
        &pool,
        position,
        pk(&f["keys"]["user_token_x"]),
        pk(&f["keys"]["user_token_y"]),
        8450,
        8520,
        program,
    );
    assert_eq!(ixs.len(), 2); // AdvanceNonceAccount first
    assert_eq!(
        ixs[0].program_id.to_string(),
        "11111111111111111111111111111111"
    );

    let bytes = encode_unsigned_tx(&ixs, &blockhash, &owner);
    let expected = b58(f["tx_claim_b58"].as_str().unwrap());
    assert_eq!(
        bytes, expected,
        "claim tx must match web3.js serialization byte-for-byte"
    );
}

#[test]
fn unsigned_rebalance_tx_matches_web3js_wire_format() {
    let f = fixtures();
    let pool = fixture_pool_ctx(&f);
    let program = pk(&f["keys"]["program"]);
    let nonce = pk(&f["keys"]["nonce"]);
    let owner = pk(&f["keys"]["owner"]);
    let position = pk(&f["keys"]["position"]);

    let blockhash: [u8; 32] = b58(f["keys"]["nonce_hash"].as_str().unwrap())
        .try_into()
        .unwrap();

    let ixs = dlmm_core::tx::build_rebalance_instructions(
        nonce,
        owner,
        &pool,
        position,
        pk(&f["keys"]["user_token_x"]),
        pk(&f["keys"]["user_token_y"]),
        8450,          // current_low
        8520,          // current_high
        8450,          // new_low
        8520,          // new_high
        8500,          // active_id
        1_500_000_000, // amount_x
        200_000_000,   // amount_y
        3,             // max_active_bin_slippage
        dlmm_core::tx::StrategyType::SpotImBalanced,
        [0u8; 64], // parameteres
        program,
    );
    assert_eq!(ixs.len(), 3); // AdvanceNonceAccount, remove, add

    let bytes = encode_unsigned_tx(&ixs, &blockhash, &owner);
    let expected = b58(f["tx_rebalance_b58"].as_str().unwrap());
    assert_eq!(
        bytes, expected,
        "rebalance tx must match web3.js serialization byte-for-byte"
    );
}

// ---------------------------------------------------------------------------
// Mechanical validation (fail-closed rules)
// ---------------------------------------------------------------------------

#[test]
fn validation_rules_fail_closed() {
    let f = fixtures();
    let pos = decode_position(&b64(&f["position_v2"])).unwrap();
    let owner = pk(&f["keys"]["owner"]);
    let stranger = Pubkey::new_unique();
    // Aligned bin array covers position bins 8450..8469 (array index 120).
    let bin_arr = decode_bin_array(&b64(&f["bin_array_aligned"])).unwrap();

    // ownership
    assert!(validate_owned(&pos, &owner).is_ok());
    assert_eq!(
        validate_owned(&pos, &stranger),
        Err(ValidationError::NotOwned)
    );

    // range
    assert!(validate_range(8400, 8600, 8500).is_ok());
    assert_eq!(
        validate_range(8600, 8400, 8500),
        Err(ValidationError::InvalidRange)
    );
    assert_eq!(
        validate_range(8400, 8499, 8500),
        Err(ValidationError::RangeDoesNotContainActiveBin)
    );

    // active-bin slippage
    assert!(validate_active_bin_slippage(8500, 8500).is_ok());
    assert!(validate_active_bin_slippage(8502, 8500).is_ok());
    assert_eq!(
        validate_active_bin_slippage(8505, 8500),
        Err(ValidationError::ActiveBinTooFar(5))
    );

    // claimable — the fixture has fees, so it passes
    assert!(validate_claimable(&pos, &[bin_arr.clone()]).is_ok());

    // bin-array range
    assert!(validate_bin_array_range(8450, 8520).is_ok());
    // 512 * 70 = 35840 → index 512 rejected
    assert!(validate_bin_array_range(-35770, 35839).is_ok());
    // -35771 → index -512 → rejected
    assert!(matches!(
        validate_bin_array_range(-35771, -35770),
        Err(ValidationError::BinArrayOverflow(_))
    ));
    assert!(matches!(
        validate_bin_array_range(35840, 35900),
        Err(ValidationError::BinArrayOverflow(_))
    ));
}

#[test]
fn empty_position_fails_claimable_check() {
    // zero liquidity, zero fees
    let f = fixtures();
    let mut bytes = b64(&f["position_v2"]);
    // zero out the liquidity shares (start of shares = 8 + 64)
    for b in bytes[8 + 64..8 + 64 + 70 * 16].iter_mut() {
        *b = 0;
    }
    let pos = decode_position(&bytes).unwrap();
    let bin_arr = decode_bin_array(&b64(&f["bin_array_aligned"])).unwrap();
    assert_eq!(total_liquidity_shares(&pos), 0);
    assert_eq!(
        validate_claimable(&pos, &[bin_arr]),
        Err(ValidationError::EmptyPosition)
    );
}

#[test]
fn maximum_slippage_constant_is_three() {
    assert_eq!(MAX_ACTIVE_BIN_SLIPPAGE, 3);
}

// ---------------------------------------------------------------------------
// `getLatestBlockhash` response decoding
// ---------------------------------------------------------------------------
//
// Regression: the no-nonce demo path used to trip `"blockhash not 32 bytes: 33"`
// because the code was decoding the base58 blockhash string as base64. The
// pinned value below is a real mainnet blockhash; it must round-trip to the
// same 32 bytes whether you decode it as base58 (correct) or base64 (the
// historical bug — note the lengths differ).
#[test]
fn get_latest_blockhash_response_decodes_as_base58() {
    use dlmm_core::rpc::decode_blockhash_from_response;

    // Real `getLatestBlockhash` response shape from mainnet-beta.
    let body = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 1,
        "result": {
            "context": { "slot": 348_000_000 },
            "value": {
                "blockhash": "9CmjKoWGqndHBRmRFL6jcc6cZs9cQttNkpTY4Y8d5vJ3",
                "lastValidBlockHeight": 348_000_016
            }
        }
    });

    let bytes = decode_blockhash_from_response(&body).expect("decode");
    assert_eq!(bytes.len(), 32);

    // Round-trip via base58 to lock the encoding: re-encoding the bytes must
    // produce the original string.
    assert_eq!(
        bs58::encode(bytes).into_string(),
        "9CmjKoWGqndHBRmRFL6jcc6cZs9cQttNkpTY4Y8d5vJ3"
    );

    // Sanity: the old base64 path produced 33 bytes — assert it here so the
    // mismatch is visible in the test output if anyone reintroduces the bug.
    let base64_len = base64::engine::general_purpose::STANDARD
        .decode("9CmjKoWGqndHBRmRFL6jcc6cZs9cQttNkpTY4Y8d5vJ3")
        .unwrap()
        .len();
    assert_eq!(base64_len, 33, "base58-as-base64 must NOT yield 32 bytes");
    assert_ne!(base64_len, bytes.len());
}

#[test]
fn get_latest_blockhash_response_rejects_malformed() {
    use dlmm_core::rpc::decode_blockhash_from_response;

    // Missing the value field.
    let v = serde_json::json!({ "jsonrpc": "2.0", "id": 1, "result": {} });
    assert!(decode_blockhash_from_response(&v).is_err());

    // Blockhash of the wrong length (31 bytes) — must error explicitly.
    let short = bs58::encode([0u8; 31]).into_string();
    let v = serde_json::json!({ "result": { "value": { "blockhash": short } } });
    match decode_blockhash_from_response(&v) {
        Err(msg) => assert!(msg.contains("not 32 bytes"), "got: {msg}"),
        Ok(_) => panic!("31-byte blockhash must be rejected"),
    }
}
